import java.util.*;

class Solution {
  public int checkWays(int[][] pairs) {
    Map<Integer, Set<Integer>> graph = new HashMap<>();
    for (int[] p : pairs) {
      graph.computeIfAbsent(p[0], k -> new HashSet<>()).add(p[1]);
      graph.computeIfAbsent(p[1], k -> new HashSet<>()).add(p[0]);
    }
    int root = -1;
    for (int node : graph.keySet())
      if (root < 0 || graph.get(node).size() > graph.get(root).size()) root = node;
    if (graph.get(root).size() != graph.size() - 1) return 0;
    int ways = 1;
    for (int node : graph.keySet()) {
      if (node == root) continue;
      Set<Integer> neighbors = graph.get(node);
      int parent = -1, parentDegree = Integer.MAX_VALUE;
      for (int candidate : neighbors) {
        if (graph.get(candidate).size() >= neighbors.size()
            && graph.get(candidate).size() < parentDegree) {
          parent = candidate;
          parentDegree = graph.get(candidate).size();
        }
      }
      if (parent < 0) return 0;
      for (int neighbor : neighbors)
        if (neighbor != parent && !graph.get(parent).contains(neighbor)) return 0;
      if (parentDegree == neighbors.size()) ways = 2;
    }
    return ways;
  }
}
